data.minimal_example:
SizedBox(
  height: 420,
  child: CalendarCarousel<String>.month(
    selectedDate: _selectedDate,
    focusedDate: _focusedDate,
    onDateSelected: (DateTime date, List<String> events) {
      setState(() {
        _selectedDate = date;
        _focusedDate = date;
      });
    },
  ),
)
